<?php
declare(strict_types=1);
/** Called only from the system-admin guarded cutover page. */
function clubTransitionView(PDO $pdo,array $run,array $entries,array $owners,array $forms):void {
    $id=(int)$run['id'];$names=array_column($owners,'jmeno','id');$draft=[];$revision=(int)$run['revision'];$history=null;
    $edit=is_scalar($_GET['edit']??null)?(string)$_GET['edit']:'';
    if($edit!==''&&isset($entries[$edit])){$entry=$entries[$edit];$draft=$entry['data']+['kind'=>$entry['kind'],'entry_key'=>$edit];$history=clubTransitionHistory($pdo,$id,$edit,(int)($_GET['history_page']??1));}
    if(isset($_GET['template'])&&is_string($_GET['template'])){try{$draft=clubTransitionTemplate($_GET['template']);if(isset($entries[$draft['entry_key']])){$edit=$draft['entry_key'];$entry=$entries[$edit];$draft=$entry['data']+['kind'=>$entry['kind'],'entry_key'=>$edit];$history=clubTransitionHistory($pdo,$id,$edit);echo '<p class="alert alert-info">Tento postup už má uloženou mapu. Načtena je její aktuální verze.</p>';}}catch(DomainException $e){echo '<p class="alert alert-warning">'.cutoverH($e->getMessage()).'</p>';}}
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&($_POST['action']??'')==='entry'){$draft=$_POST;$revision=(int)($_POST['revision']??0);}
    $stale=$revision!==(int)$run['revision'];
    ?><h3 class="h4">Mapa původních postupů</h3><p>Návrhy níže pouze předvyplní formulář. Vlastník, konkrétní stará obrazovka, historie a datum přechodu vyžadují ověření. Výběr návrhu nic nezapisuje ani nepřepíná.</p>
    <details class="mb-3"><summary>Navržené neobchodní postupy</summary><ul><?php foreach(clubTransitionCatalog() as $key=>$row):?><li><a href="?id=<?=$id?>&amp;template=<?=cutoverH($key)?>#entry-agenda"><?=cutoverH($row[0])?></a> · <?=cutoverH($row[3])?></li><?php endforeach;?></ul></details>
    <?php if($stale):?><p class="alert alert-warning">Registr byl mezitím změněn. Váš rozepsaný návrh a původní revize zůstaly zachovány. Před novým zápisem porovnejte aktuální položku; opětovné odeslání staré verze ji nepřepíše. <a href="?id=<?=$id?>&amp;edit=<?=cutoverH(urlencode((string)($draft['entry_key']??'')))?>">Načíst aktuální verzi (zahodí rozepsaný návrh)</a></p><?php endif;?>
    <h3 class="h4">Registr aktuálních položek</h3><p>Každá oprava vytvoří novou verzi. Ověření mapy obsluhou samo neschvaluje import ani odstavení služby.</p><div class="table-responsive"><table class="table"><tr><th>Položka</th><th>Postup a historie</th><th>Odpovědnost a hranice</th><th>Doložení</th><th></th></tr><?php foreach($entries as $key=>$e):$data=$e['data'];?><tr><td><?=cutoverH($data['title'])?><br><small><?=cutoverH($key)?></small></td><td><?php if($e['kind']==='agenda'):?><?=cutoverH($data['source_screen']??'Obrazovka dosud neuvedena')?> → <?=cutoverH($data['target_route']??'Cíl dosud neuveden')?><br><?=cutoverH($data['history_scope']??'Historie dosud neuvedena')?><br><strong><?=cutoverH(['proposed'=>'Návrh','verified'=>'Obsluhou ověřená mapa','blocked'=>'K dořešení'][$data['mapping_status']??'proposed'])?></strong><?php else:?><?=cutoverH($forms[$e['kind']][0])?><?php endif;?></td><td><?=cutoverH($names[$data['owner_trainer_id']]??'Neaktivní / nedostupná osoba #'.$data['owner_trainer_id'])?><br><?=cutoverH($data['boundary_at']??'')?></td><td><?=cutoverH($data['evidence'])?></td><td><a href="?id=<?=$id?>&amp;edit=<?=cutoverH(urlencode($key))?>#entry-<?=cutoverH($e['kind'])?>">Opravit / historie</a></td></tr><?php endforeach;?></table></div>
    <?php if($history):?><details open class="mb-3"><summary>Historie <?=cutoverH($edit)?> · <?=$history['total']?> verzí</summary><?php foreach($history['rows'] as $r):?><details class="mb-2"><summary><?=cutoverH('Revize '.$r['revision'].' · '.$r['created_at'].' · '.$r['actor_name'].' · '.$r['reason'])?></summary><dl><?php foreach($r['data'] as $key=>$value):?><dt><?=cutoverH($key)?></dt><dd><?=cutoverH($value)?></dd><?php endforeach;?></dl></details><?php endforeach;?><?php foreach(['Předchozí'=>$history['page']-1,'Další'=>$history['page']+1] as $label=>$page)if($page>0&&$page<=$history['pages']):?><a class="me-3" href="?id=<?=$id?>&amp;edit=<?=cutoverH(urlencode($edit))?>&amp;history_page=<?=$page?>"><?=$label?></a><?php endif;?></details><?php endif;?>
    <?php foreach($forms as $kind=>[$title,$fields]):$values=($draft['kind']??'')===$kind?$draft:[];?><details id="entry-<?=$kind?>" class="mb-3" <?=$values?'open':''?>><summary>Zapsat / opravit: <?=cutoverH($title)?></summary><form method="post" action="?id=<?=$id?>" class="card card-body"><?=csrf_field()?><input type="hidden" name="action" value="entry"><input type="hidden" name="run_id" value="<?=$id?>"><input type="hidden" name="revision" value="<?=$revision?>"><input type="hidden" name="kind" value="<?=$kind?>">
    <label>Jedinečný klíč položky<input class="form-control" name="entry_key" value="<?=cutoverH($values['entry_key']??'')?>" pattern="[a-z0-9._:-]+" required maxlength="100"></label><label>Název<input class="form-control" name="title" value="<?=cutoverH($values['title']??'')?>" required maxlength="160"></label><label>Odpovědná osoba<select class="form-select" name="owner_trainer_id" required><option value="">Vyberte výslovně</option><?php foreach($owners as $o):?><option value="<?=(int)$o['id']?>" <?=(int)($values['owner_trainer_id']??0)===(int)$o['id']?'selected':''?>><?=cutoverH($o['jmeno'])?></option><?php endforeach;?></select></label>
    <?php foreach($fields as $key=>$def):$value=$values[$key]??'';if($key==='source_key'){$choices=[''=>'Vyberte zdroj'];foreach($entries as $entryKey=>$entry)if($entry['kind']==='source')$choices[$entryKey]=$entry['data']['title'];$def=['Evidovaný zdroj',$choices];}if(is_array($def)):?><label><?=cutoverH($def[0])?><select class="form-select" name="<?=$key?>"><?php foreach($def[1] as $option=>$label):?><option value="<?=cutoverH($option)?>" <?=(string)$value===(string)$option?'selected':''?>><?=cutoverH($label)?></option><?php endforeach;?></select></label><?php else:?><label><?=cutoverH($def)?><input class="form-control" name="<?=$key?>" value="<?=cutoverH($value)?>" required maxlength="2000"></label><?php endif;endforeach;?>
    <?php if($kind==='agenda'):?><fieldset class="border p-2 mt-2"><legend class="h6">Mapa starého a nového postupu</legend><label>Původní obrazovka nebo papírový seznam<input class="form-control" name="source_screen" maxlength="500" value="<?=cutoverH($values['source_screen']??'')?>"></label><label>Cílový postup<select class="form-select" name="target_route"><option value="">Dosud neurčen</option><?php foreach(clubTransitionCatalog() as $row):?><option value="<?=cutoverH($row[2])?>" <?=($values['target_route']??'')===$row[2]?'selected':''?>><?=cutoverH($row[0].' · '.$row[3])?></option><?php endforeach;?></select></label><label>Přenášená / archivovaná historie<textarea class="form-control" name="history_scope" maxlength="2000"><?=cutoverH($values['history_scope']??'')?></textarea></label><label>Stav ověření mapy<select class="form-select" name="mapping_status"><?php foreach(['proposed'=>'Návrh','verified'=>'Konkrétní postup ověřen obsluhou','blocked'=>'K dořešení'] as $key=>$label):?><option value="<?=$key?>" <?=($values['mapping_status']??'proposed')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></fieldset><?php endif;?>
    <label>Konkrétní důkaz a jeho umístění<textarea class="form-control" name="evidence" required maxlength="2000"><?=cutoverH($values['evidence']??'')?></textarea></label><label>Důvod zápisu<input class="form-control" name="reason" value="<?=cutoverH($values['reason']??'')?>" required maxlength="1000"></label><label class="my-2"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji zápis podkladu přípravy.</label><button class="btn btn-primary">Uložit novou verzi položky</button></form></details><?php endforeach;
}
